style.css:
@-moz-document domain("roblox.com") {
/* Set custom background image for entire page */
    body {
        background-image: url("https://i.imgur.com/yourImageHere.jpg");
        background-size: cover;
        background-repeat: no-repeat;
        background-attachment: fixed;
        background-position: center center;
    }

    /* Make main containers slightly transparent */
    .container-main,
    .content,
    .game-card-container,
    .section,
    .navbar,
    .footer,
    .home-container,
    .games-page,
    .game-card,
    .game-card-thumb-container,
    .game-carousel,
    .game-carousel-title {
        background-color: rgba(255, 255, 255, 0.85) !important;
    }

    /* Optional: Make some cards semi-transparent */
    .game-card-container,
    .game-card-thumb {
        border-radius: 10px;
        backdrop-filter: blur(3px);
    }

    /* Optional: Make header/navbar transparent */
    .navbar {
        background-color: rgba(255, 255, 255, 0.6) !important;
        backdrop-filter: blur(5px);
    }
}
